func checkpointRunHandoffIfChanged(taskID, packetID, sessionID, handoffPath string, lastHash *string, force bool) (bool, error) {
	currentHash := fileHash(handoffPath)
	if currentHash == "" {
		return false, nil
	}
	if !force && lastHash != nil && *lastHash == currentHash {
